    # A damaged copy has a foreground prefix matching a fuller row, followed
    # only by background. Restore that missing suffix with the task marker 1.
    for r, row in enumerate(grid):
        nonbg = [c for c, v in enumerate(row) if v != bg]
        if not nonbg:
            continue
        last = max(nonbg)
        for template in grid:
            tcols = [c for c, v in enumerate(template) if v != bg]
            if not tcols or max(tcols) <= last:
                continue
            if row[:last + 1] != template[:last + 1]:
                continue
            for c in range(last + 1, w):
                if row[c] == bg and template[c] != bg:
                    out[r][c] = 1
            break

    # A repeated two-part stripe can signal its final background cell.
    # (Observed when a period-5 motif repeats twice across a 10-cell row.)
    for r, row in enumerate(grid):
        if w == 10 and row[-1] == bg and row[:5] == row[5:10] and row[0] != bg:
            out[r][-1] = 1
    return out
